#lang ivy1.7

# an abstract leader election protocol based on majorities

type node
type nodeset

relation member(X:node, Y:nodeset)
relation majority(X:nodeset)
function emptyset : nodeset

# the following axiom (not needed here) would create a function cycle
# axiom forall N:node. exists S:nodeset. member(N,S)

trusted isolate ns = {
    action add(n:node, s1:nodeset) returns (s2:nodeset) = {
        ensure forall N. member(N,s2) <-> (member(N, s1) | N=n);
        ensure majority(s1) -> majority(s2);
    }
}

relation vote(X:node, Y:node)
relation leader(X:node)
relation voters(X:node, Y:nodeset)

relation didNotVote(N:node) = forall V. ~vote(N, V)
relation setOverlap(S1:nodeset, S2:nodeset) = exists N. member(N,S1) & member(N,S2)

axiom forall S1:nodeset, S2:nodeset. majority(S1) & majority(S2) -> setOverlap(S1, S2)
axiom forall N. ~member(N, emptyset)

after init {
    vote(X,Y) := false;
    leader(X) := false;
    voters(X,Y) := Y = emptyset;
}

action voting(n1:node, n2:node) = {
    require didNotVote(n1);
    vote(n1, n2) := true;
}
export voting

action receive_vote(voter:node, n:node, vs:nodeset) = {
    require vote(voter, n);
    require voters(n,vs);
    require ~member(voter, vs);
    vs := ns.add(voter, vs);
    voters(n,VS) := VS = vs;
}
export receive_vote

action become_leader(n:node, vs:nodeset) = {
    require voters(n,vs);
    require majority(vs);
    leader(n) := true;
}
export become_leader

invariant [safety_unique_leader] forall X,Y. leader(X) & leader(Y) -> X=Y

Looking at this counterexample, the issue is that the protocol allows two nodes to each accumulate a majority of votes independently, violating the safety property. The key insight is that by the quorum intersection axiom, if two different nodes each have a majority set of voters, those sets must overlap (share at least one voter). But each voter votes only once, so this is impossible—if a voter is in multiple nodes' voter sets, the voter must have voted for each of those nodes, which contradicts the fact that each voter votes at most once.

The missing invariant should ensure that if a voter is in a node's voter set, then the voter must have voted for that node:

Looking at the state structure:
- `vote(V, X)` tracks that voter V voted for candidate X
- `voters(Y, S)` tracks that the voter set for candidate Y is S  
- `member(V, S)` means voter V is in set S

The invariant that enforces consistency is: if voter V is a member of candidate Y's voter set, then V must have voted for Y. This prevents different candidates from accumulating overlapping majorities.

Once this invariant is in place, if two nodes each have a majority, their voter sets must overlap (by quorum intersection), meaning they share a voter. But that voter can only have voted for one candidate, so both nodes must be the same node—preserving the safety property.

invariant vote(V, X) & voters(Y, S) & member(V, S) -> X = Y

