# A total order helper module
module total_order(r) = {
    axiom r(X, X)                       # Reflexivity
    axiom r(X, Y) & r(Y, Z) -> r(X, Z)  # Transitivity
    axiom r(X, Y) & r(Y, X) -> X = Y    # Anti-symmetry
    axiom r(X, Y) | r(Y, X)             # Totality
}

relation le(X:ballot, Y:ballot)
instantiate total_order(le)
individual negone:ballot
axiom le(negone, X)
individual max:ballot
axiom le(X, max)

individual none:value

relation member1(A:acceptor, Q:quorum1)
relation member2(A:acceptor, Q:quorum2)
axiom forall Q1:quorum1, Q2:quorum2. exists A:acceptor. member1(A, Q1) & member2(A, Q2)

relation msg_1a(B:ballot)
relation msg_1b(A:acceptor, B:ballot, MBAL:ballot, MVAL:value)
relation msg_2a(B:ballot, V:value)
relation msg_2b(A:acceptor, B:ballot, V:value)

function maxBal(A:acceptor):ballot
function maxVBal(A:acceptor):ballot
function maxVal(A:acceptor):value

# Definitions
relation chosenAt(B:ballot, V:value) = exists Q:quorum2. forall A. member2(A, Q) -> msg_2b(A, B, V)
relation chosen(V:value) = exists B. chosenAt(B, V)
relation showsSafeAt(Q:quorum1, B:ballot, V:value) = ((forall A:acceptor. member1(A, Q) -> le(B, maxBal(A))) & 
													(exists C:ballot. ~le(B, C) & 
														(C ~= negone -> exists A:acceptor. member1(A, Q) & msg_2b(A, C, V)) & 
														(forall D:ballot. (~le(D, C) & ~le(B, D)) -> 
															(forall A:acceptor. member1(A, Q) -> (forall Vd:value. ~msg_2b(A, D, Vd))))))
relation isSafeAt(B:ballot, V:value) = exists Q:quorum1. showsSafeAt(Q, B, V)

relation showsSafeAtPaxosSimple(Q:quorum1, B:ballot, V:value) =
		(	(forall A. member1(A, Q) -> exists MBAL, MVAL. msg_1b(A, B, MBAL, MVAL)) & 
		(	(forall A, MBAL, MVAL. ~(member1(A, Q) & msg_1b(A, B, MBAL, MVAL) & msg_2b(A, MBAL, MVAL))) |
			(exists MBAL.	(exists A. member1(A, Q) & msg_1b(A, B, MBAL, V) & msg_2b(A, MBAL, V)) &
							(forall A, MBAL2, MVAL2. member1(A, Q) & msg_1b(A, B, MBAL2, MVAL2) & msg_2b(A, MBAL2, MVAL2) -> le(MBAL2, MBAL)))
		))
relation isSafeAtPaxosSimple(B:ballot, V:value) = exists Q:quorum1. showsSafeAtPaxosSimple(Q, B, V)

relation showsSafeAtPaxos(Q:quorum1, B:ballot, V:value) =
		(	(forall A. member1(A, Q) -> exists MBAL, MVAL. msg_1b(A, B, MBAL, MVAL)) & 
			(	(forall A, MBAL, MVAL. ~(member1(A, Q) & msg_1b(A, B, MBAL, MVAL) & MBAL ~= negone)) |
				(exists MBAL.	(exists A. member1(A, Q) & msg_1b(A, B, MBAL, V) & (MBAL ~= negone)) &
								(forall A, MBAL2, MVAL2. member1(A, Q) & msg_1b(A, B, MBAL2, MVAL2) & (MBAL2 ~= negone) -> le(MBAL2, MBAL)))
		))
relation isSafeAtPaxos(B:ballot, V:value) = exists Q:quorum1. showsSafeAtPaxos(Q, B, V)

after init {
    maxBal(A) := negone;
    maxVBal(A) := negone;
    maxVal(A) := none;
    msg_1a(B) := false;
    msg_1b(A, B, MBAL, MVAL) := false;
    msg_2a(B, V) := false;
    msg_2b(A, B, V) := false;
}

action phase_1a(b:ballot) = {
    require b ~= negone;

    msg_1a(b) := true;
}

action phase_1b(a:acceptor, b:ballot) = {
    require b ~= negone;
    require msg_1a(b);
    require ~le(b, maxBal(a));

    maxBal(a) := b;
    msg_1b(a, b, maxVBal(a), maxVal(a)) := true;
}

action phase_2a(b:ballot, v:value) = {
    require b ~= negone;
    require v ~= none;
    require ~(exists V. msg_2a(b, V));
	require isSafeAtPaxos(b, v);

    msg_2a(b, v) := true;
}

action phase_2b(a:acceptor, b:ballot, v:value) = {
    require b ~= negone;
    require v ~= none;
    require msg_2a(b, v);
    require le(maxBal(a), b);

    maxBal(a) := b;
    maxVBal(a) := b;
    maxVal(a) := v;
    msg_2b(a, b, v) := true;
}

