    maxBal(A) := negone;
    maxVBal(I, A) := negone;
    maxVal(I, A) := none;
    msg_1a(B) := false;
    msg_1b(I, A, B, MBAL, MVAL) := false;
    msg_2a(I, B, V) := false;
    msg_2b(I, A, B, V) := false;
    propCmds(V) := false;
